// Turns whatever the crew sends into one clean notification row
return $input.all().map(item => {
  const b = item.json.body || item.json;
  if (b.type === 'escalation') {
    return { json: {
      channel: 'officer_alert',
      complaint_id: (b.items || []).map(i => i.complaint_id).join(', '),
      recipient: 'Level 2 and Level 3 officers',
      language: 'en',
      priority: 'escalation',
      message: b.note,
      payload: JSON.stringify(b),
    }};
  }
  return { json: {
    channel: 'citizen_reply',
    complaint_id: b.complaint_id,
    recipient: 'Citizen (complaint ' + b.complaint_id + ')',
    language: b.language,
    priority: b.priority,
    message: b.message,
    payload: JSON.stringify(b),
  }};
});
